DATA = {
    "feeds": ["A", "B"],
    "nutrients": ["protein", "fat"],
    "cost": {"A": 100, "B": 80},
    "content": {
        "protein": {"A": 10, "B": 7},
        "fat": {"A": 8, "B": 15},
    },
    "requirement": {"protein": 30, "fat": 50},
}


def build_model(data=None):
    d = data or DATA

    model = pyo.ConcreteModel()

    model.feeds = pyo.Set(initialize=d["feeds"])
    model.nutrients = pyo.Set(initialize=d["nutrients"])

    # x[i] = kilograms of feed i used (nonnegative real)
    def x_bounds(m, i):
        return (0, None)

    model.x = pyo.Var(model.feeds, domain=pyo.NonNegativeReals, bounds=x_bounds)

    # Objective: minimize total cost of the mixture
    def obj_rule(m):
        return sum(d["cost"][i] * m.x[i] for i in m.feeds)

    model.obj = pyo.Objective(expr=obj_rule, sense=pyo.minimize)

    # Nutrient requirement constraints (at least the stated units)
    def nutrient_rule(m, n):
        return sum(d["content"][n][i] * m.x[i] for i in m.feeds) >= d["requirement"][n]

    model.nutrient_constraint = pyo.Constraint(model.nutrients, rule=nutrient_rule)

    return model

import pyomo.environ as pyo

DATA = {
