        "protein": {"A": 10, "B": 7},
        "fat": {"A": 8, "B": 15},
    },
    "requirement": {"protein": 30, "fat": 50},
}


def build_model(data=None):
    d = data or DATA

    model = pyo.ConcreteModel()

    model.feeds = pyo.Set(initialize=d["feeds"])
    model.nutrients = pyo.Set(initialize=d["nutrients"])

    model.amount = pyo.Var(model.feeds, within=pyo.NonNegativeReals)

    def cost_rule(m):
        return sum(d["cost"][i] * m.amount[i] for i in m.feeds)

    model.obj = pyo.Objective(expr=cost_rule, sense=pyo.minimize)

    def nutrient_rule(m, n):
        return sum(d["content"][n][i] * m.amount[i] for i in m.feeds) >= d["requirement"][n]

    model.nutrient_requirement = pyo.Constraint(model.nutrients, rule=nutrient_rule)

    return model
